package main

import (
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/wailsapp/wails/v3/pkg/application"
	"github.com/wailsapp/wails/v3/pkg/updater"
	"github.com/wailsapp/wails/v3/pkg/updater/providers/endpoint"
)

//go:embed version.txt
var versionFile string

// updateKey is the Ed25519 public key that signs the update manifest's
// artifact digests, pinned at build time so the manifest cannot nominate its
// own trust anchor. Generated by scripts/gen-signing-key.sh; the private half
// lives in the DESKTOP_UPDATE_SIGNING_KEY repository secret.
//
//go:embed update-key.pem
var updateKey []byte

// Version is the running desktop version. version.txt is the single source of
// truth: the release workflow reads it too, and refuses to publish when the
// pushed tag disagrees with it.
var Version = strings.TrimSpace(versionFile)

// manifestURL points at a rolling `desktop-latest` release whose only asset is
// the update manifest. The versioned `desktop/v*` tags cannot serve it: the
// repo's releases/latest pointer belongs to the mobile app, and the GitHub
// updater provider can't read a `desktop/v*` tag as a semver anyway.
const manifestURL = "https://github.com/nonbili/Nori/releases/download/desktop-latest/latest.json"

// updateWindowCSS is layered over the built-in update window. Its stock
// `.u__btn:hover:not(:disabled)` rule outranks `.u__btn--primary`, so a hovered
// primary button takes the neutral surface background under its white label
// and vanishes.
const updateWindowCSS = `.u__btn--primary:hover:not(:disabled) { background: var(--accent); }`

type UpdateService struct {
	app       *application.App
	mu        sync.Mutex
	available bool
}

// CheckNow also works when automatic startup checks are disabled.
func (s *UpdateService) CheckNow() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if !s.available {
		return fmt.Errorf("updates are unavailable in this build")
	}
	return s.app.Updater.CheckAndInstall(context.Background())
}

// Missing preferences keep startup network checks off, including older installations.
func checkForUpdatesOnStartupPreference(state string) bool {
	var stored struct {
		Preferences struct {
			Enabled bool `json:"checkForUpdatesOnStartup"`
		} `json:"preferences"`
	}
	return json.Unmarshal([]byte(state), &stored) == nil && stored.Preferences.Enabled
}

// initUpdater wires up the Wails updater, which swaps the running binary (or
// the .app bundle) in place and offers a restart. The DMG and the NSIS
// installer are first-install channels only; updates arrive as the plain
// archives the manifest points at.
func initUpdater(app *application.App, store *StoreService) {
	service := &UpdateService{app: app}
	app.RegisterService(application.NewService(service))
	// Inside an AppImage the running binary lives on a read-only mount, and
	// the path an in-place swap would target is the mount, not the image the
	// user actually launched. Those builds update through the AppImage.
	if os.Getenv("APPIMAGE") != "" {
		return
	}

	provider, err := endpoint.New(endpoint.Config{URL: manifestURL, Channel: "stable"})
	if err != nil {
		log.Printf("updater: %v", err)
		return
	}
	if err := app.Updater.Init(updater.Config{
		CurrentVersion: Version,
		Providers:      []updater.Provider{provider},
		PublicKey:      updateKey,
		Window:         &updater.BuiltinWindow{CSS: updateWindowCSS},
	}); err != nil {
		log.Printf("updater: %v", err)
		return
	}

	service.available = true
	raw, err := store.Get(stateKey)
	if err != nil || !checkForUpdatesOnStartupPreference(raw) {
		return
	}
	// Only open the updater window when a startup check finds a release.
	go func() {
		service.mu.Lock()
		defer service.mu.Unlock()
		ctx := context.Background()
		rel, err := app.Updater.Check(ctx)
		if err != nil || rel == nil {
			return
		}
		if err := app.Updater.CheckAndInstall(ctx); err != nil {
			log.Printf("updater: %v", err)
		}
	}()
}

// runUpdateHelper handles updates before loading the store or starting Wails.
// Log before restaging: a Windows install under Program Files can fail here
// without reaching Wails' helper logger, after the original app has exited.
func runUpdateHelper() {
	if os.Getenv("WAILS_UPDATER_HELPER") != "1" {
		return
	}
	logPath := os.Getenv("WAILS_UPDATER_HELPER_LOG")
	if logPath == "" {
		logPath = filepath.Join(os.TempDir(), fmt.Sprintf("wails-update-%d.log", os.Getpid()))
		_ = os.Setenv("WAILS_UPDATER_HELPER_LOG", logPath)
	}
	file, err := os.OpenFile(logPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
	if err != nil {
		log.Printf("updater: open helper log: %v", err)
	} else {
		log.SetOutput(file)
		// Wails opens the same log itself after restaging. Close our handle
		// first so it can reopen the file on Windows too.
	}
	log.Print("updater: preparing update helper")
	if err := restageUpdate(); err != nil {
		log.Fatalf("updater: %v", err)
	}
	if file != nil {
		log.SetOutput(os.Stderr)
		_ = file.Close()
	}
	updater.HandleHelperMode()
}

// restageUpdate moves a downloaded update next to the binary it replaces.
//
// The updater stages downloads under os.TempDir and its helper swaps them in
// with a bare os.Rename, after deleting the target. A rename cannot cross
// filesystems, and /tmp is commonly its own (tmpfs on Linux), so for an
// install under $HOME the swap deleted the binary and then failed; the
// helper's restore path relaunches with the helper environment still set, so
// it looped deleting the binary again. Staging beside the target keeps the
// rename on one filesystem.
func restageUpdate() error {
	if os.Getenv("WAILS_UPDATER_HELPER") != "1" {
		return nil
	}
	target, staged := os.Getenv("WAILS_UPDATER_HELPER_TARGET"), os.Getenv("WAILS_UPDATER_HELPER_NEW")
	local := target + ".new"
	if target == "" || staged == "" || staged == local {
		return nil
	}
	if err := moveAcross(staged, local); err != nil {
		// Leaving the staged path alone would hand the helper the
		// cross-filesystem rename this exists to avoid; the install is
		// untouched so far, so give up on this update instead.
		_ = os.RemoveAll(local)
		return fmt.Errorf("restage %s beside %s: %w", staged, target, err)
	}
	if dir := filepath.Dir(staged); strings.HasPrefix(filepath.Base(dir), "wails-update-") {
		_ = os.RemoveAll(dir)
	}
	_ = os.Setenv("WAILS_UPDATER_HELPER_NEW", local)
	return nil
}

// moveAcross renames src to dst, copying instead when they sit on different
// filesystems. src is a single binary, or a .app bundle directory on macOS.
func moveAcross(src, dst string) error {
	if err := os.RemoveAll(dst); err != nil {
		return err
	}
	if os.Rename(src, dst) == nil {
		return nil
	}
	info, err := os.Stat(src)
	if err != nil {
		return err
	}
	if info.IsDir() {
		return os.CopyFS(dst, os.DirFS(src))
	}
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	return os.WriteFile(dst, data, info.Mode().Perm())
}
